<?php
 namespace Pterodactyl\Services\Dezerx\ServerCreate; use Throwable; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\Cache; use Illuminate\Contracts\Cache\LockTimeoutException; use Illuminate\Validation\ValidationException; use Illuminate\Contracts\Validation\Factory as ValidationFactory; use Pterodactyl\Facades\Activity; use Pterodactyl\Models\Egg; use Pterodactyl\Models\User; use Pterodactyl\Models\Server; use Pterodactyl\Models\EggVariable; use Pterodactyl\Models\Dezerx\FreeServer; use Pterodactyl\Exceptions\DisplayException; use Pterodactyl\Services\Servers\SuspensionService; use Pterodactyl\Services\Servers\ServerCreationService; use Pterodactyl\Services\Deployment\AllocationSelectionService; class ServerFactory { private const LOCK = 'dezerx:server-create'; private const LOCK_SECONDS = 60; public function __construct( private ServerCreationService $creation, private SuspensionService $suspension, private ValidationFactory $validator, private NodeCapacity $capacity, private AllocationSelectionService $allocations, ) { } public function create( User $user, Egg $egg, int $location, string $name, array $environment = [], array $wanted = [], ): Server { return $this->serialised( fn () => $this->provision($user, $egg, $location, $name, $environment, $wanted), ); } public function serialised(callable $callback): mixed { $lock = Cache::lock(self::LOCK, self::LOCK_SECONDS); try { $lock->block(10); } catch (LockTimeoutException) { throw new DisplayException('The panel is busy creating another server. Try again in a moment.'); } try { return $callback(); } finally { $lock->release(); } } public function renew(FreeServer $entry): FreeServer { $from = $entry->renew_at !== null && $entry->renew_at->isFuture() ? CarbonImmutable::parse($entry->renew_at) : CarbonImmutable::now(); $entry->forceFill([ 'renew_at' => ServerCreate::nextDeadline($from), 'last_renewed_at' => CarbonImmutable::now(), 'renewals' => $entry->renewals + 1, ]); if ($entry->wasSuspendedForNonRenewal()) { $server = $entry->server; if ($server !== null && $server->isSuspended()) { $this->suspension->toggle($server, SuspensionService::ACTION_UNSUSPEND); } $entry->suspended_at = null; } $entry->save(); if ($entry->server !== null) { Activity::event('server:free.renew') ->subject($entry->server) ->property([ 'renews_at' => $entry->renew_at?->toIso8601String(), 'renewals' => $entry->renewals, ]) ->log(); } return $entry; } public function cleanName(string $name): string { $name = preg_replace('/[\x00-\x1F\x7F]+/u', '', trim($name)) ?? ''; $name = preg_replace('/\s+/u', ' ', $name) ?? ''; return mb_substr($name, 0, 40); } private function provision( User $user, Egg $egg, int $location, string $name, array $environment, array $wanted, ): Server { $refusal = ServerCreate::refusal($user); if ($refusal !== null) { throw new DisplayException($this->explain($refusal)); } if (!ServerCreate::offers($location)) { throw new DisplayException('That location is not one this panel offers.'); } $resources = ServerCreate::chosen($user, $wanted); $images = array_values((array) $egg->docker_images); $data = [ 'name' => $this->prefixed($name), 'description' => '', 'owner_id' => $user->id, 'egg_id' => $egg->id, 'nest_id' => $egg->nest_id, 'startup' => (string) $egg->startup, 'image' => $images[0] ?? '', 'environment' => $this->environment($egg, $environment), 'memory' => $resources['memory'], 'swap' => $resources['swap'], 'disk' => $resources['disk'], 'io' => $resources['io'], 'cpu' => $resources['cpu'], 'threads' => null, 'oom_disabled' => ServerCreate::flag('oom_disabled'), 'database_limit' => $resources['databases'], 'allocation_limit' => $resources['allocations'], 'backup_limit' => $resources['backups'], 'skip_scripts' => false, 'start_on_completion' => ServerCreate::flag('start_on_completion'), ]; $nodes = $this->capacity->viableIn($location, $resources); if ($nodes === []) { throw new DisplayException('That location has no room left. Pick another one.'); } $allocation = $this->allocations->setDedicated(false)->setNodes($nodes)->setPorts([])->handle(); $data['allocation_id'] = $allocation->id; $data['node_id'] = $allocation->node_id; $server = $this->creation->handle($data); try { FreeServer::query()->create([ 'server_id' => $server->id, 'user_id' => $user->id, 'renew_at' => ServerCreate::nextDeadline(), 'last_renewed_at' => null, 'renewals' => 0, ]); } catch (Throwable $exception) { app(\Pterodactyl\Services\Servers\ServerDeletionService::class)->withForce()->handle($server); throw $exception; } Activity::event('server:free.create') ->subject($server) ->property([ 'egg' => $egg->uuid, 'location' => $location, ]) ->log(); return $server; } private function prefixed(string $name): string { $prefix = (string) ServerCreate::setting('name_prefix'); return trim($prefix === '' ? $name : $prefix . ' ' . $name); } private function environment(Egg $egg, array $supplied): array { $variables = $egg->variables()->get(); $open = ServerCreate::flag('variables'); $out = []; $data = []; $rules = []; $names = []; foreach ($variables as $variable) { $editable = $open && $variable->user_editable && $variable->user_viewable; $value = $editable && array_key_exists($variable->env_variable, $supplied) ? (string) $supplied[$variable->env_variable] : (string) $variable->default_value; $out[$variable->env_variable] = $value; if ($editable) { $data[$variable->env_variable] = $value; $rules[$variable->env_variable] = $variable->rules; $names[$variable->env_variable] = $variable->name; } } if ($rules !== []) { $check = $this->validator->make($data, $rules, [], $names); if ($check->fails()) { throw new ValidationException($check); } } return $out; } private function explain(string $refusal): string { return match ($refusal) { 'demo' => 'Demo accounts cannot create servers.', 'totp' => 'Two-factor authentication has to be on before you can create a server.', 'discord' => 'Link your Discord account before you can create a server.', 'young' => 'This account is too new to create a server yet.', 'limit' => 'You already have as many servers as this panel hands out.', 'full' => 'Every free server this panel offers has been taken.', default => 'Creating servers is not available right now.', }; } } 